#define REGTRACE_TX_ISP_MODULE_CLK_PTR_OFFSET TX_ISP_ABI_LEGACY_SUBDEV_CLOCKS_OFFSET
#define REGTRACE_TX_ISP_MODULE_IRQDEV_OFFSET TX_ISP_ABI_LEGACY_SUBDEV_IRQDEV_OFFSET
#define REGTRACE_TX_ISP_MODULE_CLK_NUM_OFFSET TX_ISP_ABI_LEGACY_SUBDEV_CLK_NUM_OFFSET
#define REGTRACE_TX_ISP_SUBDEV_OPS_OFFSET TX_ISP_ABI_LEGACY_SUBDEV_OPS_OFFSET
#define REGTRACE_TX_ISP_MODULE_OUTPAD_COUNT_OFFSET TX_ISP_ABI_LEGACY_SUBDEV_PAD_COUNT0
#define REGTRACE_TX_ISP_MODULE_INPAD_COUNT_OFFSET TX_ISP_ABI_LEGACY_SUBDEV_PAD_COUNT1
#define REGTRACE_TX_ISP_MODULE_OUTPADS_OFFSET TX_ISP_ABI_LEGACY_SUBDEV_PAD_PTR0
#define REGTRACE_TX_ISP_MODULE_INPADS_OFFSET TX_ISP_ABI_LEGACY_SUBDEV_PAD_PTR1
#define REGTRACE_TX_ISP_MODULE_SELF_OFFSET TX_ISP_ABI_LEGACY_SUBDEV_PRIVATE0
#define REGTRACE_TX_ISP_PAD_STRIDE TX_ISP_ABI_PAD_STRIDE
#define REGTRACE_TX_ISP_PADTYPE_INPUT TX_ISP_ABI_PADTYPE_INPUT
#define REGTRACE_TX_ISP_PADTYPE_OUTPUT TX_ISP_ABI_PADTYPE_OUTPUT
#define REGTRACE_TX_ISP_TYPE_SUBDEV 1
#define REGTRACE_TX_ISP_TYPE_WIDGET 2
#define REGTRACE_TX_ISP_SUBDEV_SENSOR_OPS_OFFSET 0x0c
#define REGTRACE_TX_ISP_EVENT_SENSOR_INT_TIME 0x02000005U
#define REGTRACE_TX_ISP_EVENT_SENSOR_AGAIN 0x02000007U
#define REGTRACE_TX_ISP_EVENT_SENSOR_FPS 0x0200000aU
#define REGTRACE_TX_ISP_EVENT_SYNC_SENSOR_ATTR 0x01000001U
#define REGTRACE_TX_ISP_MODULE_NOTIFY_OFFSET TX_ISP_ABI_LEGACY_MODULE_NOTIFY_OFFSET
#define REGTRACE_TX_ISP_EVENT_SENSOR_EXPO 0x02000016U

static int regtrace_t23_ops_has_sensor_table(uintptr_t ops)
{
    return regtrace_t23_valid_ptr(ops) &&
        *(uint32_t *)(ops + REGTRACE_TX_ISP_SUBDEV_SENSOR_OPS_OFFSET) != 0;
}

static int regtrace_t23_is_internal_isp_platform(const char *name)
{
    return name &&
        (!strcmp(name, "isp-w00") ||
         !strcmp(name, "isp-w01") ||
         !strcmp(name, "isp-w02") ||
         !strcmp(name, "isp-m0") ||
         !strcmp(name, "isp-fs") ||
         !strcmp(name, "isp-ivdc") ||
         !strcmp(name, "tx-isp"));
}

static int regtrace_t23_capture_sensor_subdev(uintptr_t pdev,
                                              uintptr_t sd,
                                              uintptr_t ops)
{
    const char *name = "?";

    if (!sd || !regtrace_t23_ops_has_sensor_table(ops))
        return 0;

    if (pdev) {
        struct platform_device *platform = (struct platform_device *)pdev;
        if (platform->name)
            name = platform->name;
    }
    if (regtrace_t23_is_internal_isp_platform(name))
        return 0;

    regtrace_t23_sensor_sd = (struct tx_isp_subdev *)sd;
    regtrace_t23_sensor_identified = false;
    regtrace_t23_sensor_initialized = false;
    regtrace_t23_sensor_streaming = false;
    regtrace_t23_sensor_fps_request = 0;
    regtrace_t23_install_sensor_notify(sd);
    regtrace_t23_seed_sensor_caches("sensor-subdev-init");
    printk(KERN_INFO "t23: captured external sensor subdev name=%s sd=%p ops=%p\n",
           name, (void *)sd, (void *)ops);
    return 1;
}

static int regtrace_t23_subdev_init_pads(unsigned char *sd, const unsigned char *pdata)
{
    const unsigned char *pads;
    unsigned int pads_num;
    unsigned int i;
    unsigned int out_count = 0;
    unsigned int in_count = 0;
    unsigned char *outpads = NULL;
    unsigned char *inpads = NULL;
    unsigned int out_index = 0;
    unsigned int in_index = 0;

    if (!sd || !pdata)
        return -EINVAL;

    pads_num = pdata[12];
    pads = *(const unsigned char **)(pdata + 16);
    if (!pads || !pads_num)
        return 0;

    for (i = 0; i < pads_num; i++) {
        if (pads[i * 2] == REGTRACE_TX_ISP_PADTYPE_OUTPUT)
            out_count++;
        else if (pads[i * 2] == REGTRACE_TX_ISP_PADTYPE_INPUT)
            in_count++;
    }

    if (out_count) {
        outpads = private_kmalloc(out_count * REGTRACE_TX_ISP_PAD_STRIDE, GFP_KERNEL);
        if (!outpads)
            return -ENOMEM;
        memset(outpads, 0, out_count * REGTRACE_TX_ISP_PAD_STRIDE);
    }

    if (in_count) {
        inpads = private_kmalloc(in_count * REGTRACE_TX_ISP_PAD_STRIDE, GFP_KERNEL);
        if (!inpads) {
            private_kfree(outpads);
            return -ENOMEM;
        }
        memset(inpads, 0, in_count * REGTRACE_TX_ISP_PAD_STRIDE);
    }

    for (i = 0; i < pads_num; i++) {
        unsigned int type = pads[i * 2];
        unsigned int links = pads[i * 2 + 1];
        unsigned char *pad = NULL;
        unsigned int index;

        if (type == REGTRACE_TX_ISP_PADTYPE_OUTPUT) {
            index = out_index++;
            pad = outpads + index * REGTRACE_TX_ISP_PAD_STRIDE;
        } else if (type == REGTRACE_TX_ISP_PADTYPE_INPUT) {
            index = in_index++;
            pad = inpads + index * REGTRACE_TX_ISP_PAD_STRIDE;
        } else {
            continue;
        }

        *(uint32_t *)(pad + TX_ISP_ABI_PAD_OWNER_OFFSET) = (uint32_t)(uintptr_t)sd;
        *(uint8_t *)(pad + TX_ISP_ABI_PAD_INDEX_OFFSET) = index;
        *(uint8_t *)(pad + TX_ISP_ABI_PAD_TYPE_OFFSET) = type;
        *(uint8_t *)(pad + TX_ISP_ABI_PAD_LINKS_TYPE_OFFSET) = links;
        *(uint8_t *)(pad + TX_ISP_ABI_PAD_STATE_OFFSET) = TX_ISP_ABI_PADSTATE_FREE;
        tx_isp_subdev_init_link_record((void *)pad);
    }

    *(uint16_t *)(sd + REGTRACE_TX_ISP_MODULE_OUTPAD_COUNT_OFFSET) = out_count;
    *(uint16_t *)(sd + REGTRACE_TX_ISP_MODULE_INPAD_COUNT_OFFSET) = in_count;
    *(uint32_t *)(sd + REGTRACE_TX_ISP_MODULE_OUTPADS_OFFSET) = (uint32_t)(uintptr_t)outpads;
    *(uint32_t *)(sd + REGTRACE_TX_ISP_MODULE_INPADS_OFFSET) = (uint32_t)(uintptr_t)inpads;

    printk(KERN_INFO "t23: subdev pads sd=%p out=%u in=%u outpads=%p inpads=%p\n",
           sd, out_count, in_count, outpads, inpads);
    return 0;
}

int32_t tx_isp_subdev_init(uintptr_t a0, uintptr_t a1, uint32_t a2)
{
    struct platform_device *pdev = (struct platform_device *)a0;
    unsigned char *sd = (unsigned char *)a1;
    unsigned char *pdata;
    int ret;

    if (!a0 || !a1)
        return -EINVAL;

    pdata = pdev->dev.platform_data;
    *(uint32_t *)(sd + REGTRACE_TX_ISP_SUBDEV_OPS_OFFSET) = a2;
    *(uint32_t *)(sd + REGTRACE_TX_ISP_MODULE_SELF_OFFSET) = (uint32_t)(uintptr_t)sd;
    regtrace_t23_capture_sensor_subdev(a0, a1, a2);
    if (pdata) {
        *(uint32_t *)(sd + REGTRACE_TX_ISP_MODULE_CLK_NUM_OFFSET) = pdata[4];
        if (pdata[0] == REGTRACE_TX_ISP_TYPE_SUBDEV ||
            pdata[0] == REGTRACE_TX_ISP_TYPE_WIDGET) {
            ret = isp_subdev_init_clks(sd, *(int32_t **)(pdata + 8));
            if (ret)
                return ret;
        }
        if (pdata[0] == REGTRACE_TX_ISP_TYPE_SUBDEV) {
            ret = regtrace_t23_subdev_init_pads(sd, pdata);
            if (ret)
                return ret;
        }
    }
    private_platform_set_drvdata(pdev, (void *)a1);
    printk(KERN_INFO "t23: subdev init dev=%s sd=%p ops=%p pdata=%p\n",
           pdev->name, sd, (void *)(uintptr_t)a2, pdata);
    return 0;
}
void tx_isp_t23_sinfo_sensor_unbound(void *subdev, struct module *owner);

int32_t tx_isp_subdev_deinit(uintptr_t arg1)
{
    if (arg1)
        *(uint32_t *)((char *)arg1 + REGTRACE_TX_ISP_SUBDEV_OPS_OFFSET) = 0;
    /* A sensor's remove() frees the subdev right after this call. */
    if (arg1 && (uintptr_t)regtrace_t23_sensor_sd == arg1)
        tx_isp_t23_sinfo_sensor_unbound((void *)arg1, NULL);
    return 0;
}

void tx_isp_t23_sinfo_driver_added(struct i2c_driver *drv,
                                   int default_i2c_addr,
                                   struct module *owner)
{
    printk(KERN_INFO "t23: sensor-info driver add %s addr=0x%x\n",
           drv && drv->driver.name ? drv->driver.name : "unknown",
           default_i2c_addr);
    regtrace_t23_sensor_driver = drv;
    regtrace_t23_set_sensor_owner(owner);
    if (atomic_read(&regtrace_tx_isp_open_count) > 0)
        regtrace_t23_pin_sensor_owner();
    regtrace_t23_ensure_sensor_client(drv,
                                      (unsigned short)default_i2c_addr,
                                      "sinfo-driver-add");
}

void tx_isp_t23_sinfo_driver_removing(struct i2c_driver *drv)
{
    regtrace_t23_release_sensor_client(drv, "sinfo-driver-del");
}

void tx_isp_t23_sinfo_sensor_bound(void *subdev, struct module *owner)
{
    struct tx_isp_subdev *sd = subdev;

    if (regtrace_t23_sensor_sd != sd)
        regtrace_t23_sensor_fps_request = 0;
    regtrace_t23_sensor_sd = sd;
    regtrace_t23_sensor_identified = false;
    regtrace_t23_sensor_initialized = false;
    regtrace_t23_sensor_streaming = false;
    regtrace_t23_install_sensor_notify((uintptr_t)sd);
    regtrace_t23_seed_sensor_caches("sensor-bind");
    printk(KERN_INFO "t23: sensor bind sd=%p owner=%p\n",
           sd, owner);
}

void tx_isp_t23_sinfo_sensor_unbound(void *subdev, struct module *owner)
{
    struct tx_isp_subdev *sd = subdev;

    (void)owner;
    if (regtrace_t23_sensor_sd == sd) {
        regtrace_t23_sensor_sd = NULL;
        regtrace_t23_sensor_identified = false;
        regtrace_t23_sensor_initialized = false;
        regtrace_t23_sensor_streaming = false;
    }
}

static int regtrace_t23_vin_proc_init(void)
{
    regtrace_t23_isp_proc_root = proc_mkdir("jz/isp", NULL);
    if (!regtrace_t23_isp_proc_root)
        return -ENOMEM;

    if (!proc_create("vin", 0644, regtrace_t23_isp_proc_root,
                     &video_input_cmd_fops)) {
        remove_proc_subtree("jz/isp", NULL);
        regtrace_t23_isp_proc_root = NULL;
        return -ENOMEM;
    }
    if (!proc_create("isp-w02", 0644, regtrace_t23_isp_proc_root,
                     &isp_vic_frd_fops)) {
        remove_proc_subtree("jz/isp", NULL);
        regtrace_t23_isp_proc_root = NULL;
        return -ENOMEM;
    }
    if (!proc_create("isp-m0", 0444, regtrace_t23_isp_proc_root,
                     &regtrace_t23_isp_m0_proc_fops)) {
        remove_proc_subtree("jz/isp", NULL);
        regtrace_t23_isp_proc_root = NULL;
        return -ENOMEM;
    }

    return 0;
}

static void regtrace_t23_vin_proc_exit(void)
{
    if (regtrace_t23_isp_proc_root) {
        remove_proc_subtree("jz/isp", NULL);
        regtrace_t23_isp_proc_root = NULL;
    }
}

