        *(uint16_t *)(fs + REGTRACE_TX_ISP_MODULE_OUTPAD_COUNT_OFFSET);
    *(uint32_t *)(fs + 228) = 1;
    *(uint32_t *)(fs + 52) = (uint32_t)(uintptr_t)&isp_framesource_fops;
    regtrace_t23_fs_sd = fs;
