MODULE_PARM_DESC(msca_rel_origin, "write the channel window origin relative to the global MSCA window");

static void regtrace_t23_msca_global_origin(uint32_t *left, uint32_t *top)
{
    uint32_t min_left = 0xffffU, min_top = 0xffffU;
    int channel;

    for (channel = 0; channel < 3; channel++) {
        const unsigned char *c = msca + channel * 56U;
        uint32_t l, t;

        if (!c[0])
            continue;
        l = regtrace_t23_get_le32(c + 0x10);
        t = regtrace_t23_get_le32(c + 0x14);
        if (l < min_left)
            min_left = l;
        if (t < min_top)
            min_top = t;
    }
    *left = min_left == 0xffffU ? 0 : min_left;
    *top = min_top == 0xffffU ? 0 : min_top;
}

int32_t tisp_msca_init_chx_cfg(uint32_t unused, uint32_t channel,
                               uintptr_t cfg_ptr)
{
    unsigned char *cfg = (unsigned char *)cfg_ptr;
    unsigned char *params;
    uint32_t base;
    uint32_t target_width;
    uint32_t target_height;
    uint32_t crop_left;
    uint32_t crop_top;
    uint32_t crop_width;
    uint32_t crop_height;
    uint32_t value;
    uint32_t out_control;

    (void)unused;
    channel &= 0xffU;
    if (!cfg || channel >= 3)
        return -EINVAL;

    if (channel == 0)
        params = msca_ch0_scale_paras;
    else if (channel == 1)
        params = msca_ch1_scale_paras;
    else
        params = msca_ch2_scale_paras;

    base = (channel + 0xd1U) << 8;
    {
        uint32_t origin_left = 0, origin_top = 0;

        if (regtrace_t23_msca_rel_origin)
            regtrace_t23_msca_global_origin(&origin_left, &origin_top);
        value = ((regtrace_t23_get_le32(cfg + 0x10) - origin_left) << 16) |
            (regtrace_t23_get_le32(cfg + 0x14) - origin_top);
    }
    system_reg_write(base + 0x00, value);
    target_width = regtrace_t23_get_le32(cfg + 0x20);
    target_height = regtrace_t23_get_le32(cfg + 0x24);
    system_reg_write(base + 0x04, (target_width << 16) | target_height);

    crop_left = regtrace_t23_get_le32(cfg + 0x28);
    crop_top = regtrace_t23_get_le32(cfg + 0x2c);
    crop_width = regtrace_t23_get_le32(cfg + 0x30);
    crop_height = regtrace_t23_get_le32(cfg + 0x34);
    if (target_width < crop_left + crop_width) {
        crop_width = target_width - crop_left;
        regtrace_t23_put_le32(cfg + 0x30, crop_width);
    }
    if (target_height < crop_top + crop_height) {
        crop_height = target_height - crop_top;
        regtrace_t23_put_le32(cfg + 0x34, crop_height);
    }
    system_reg_write(base + 0x08,
                     ((crop_left & 0x1fffU) << 16) |
                     (crop_top & 0x0fffU));
    system_reg_write(base + 0x0c,
                     ((crop_width & 0x1fffU) << 16) |
                     (crop_height & 0x0fffU));

    system_reg_write(base + 0x70,
                     ((regtrace_t23_get_le32(params + 0x04) & 0x3ffU) << 16) |
                     (regtrace_t23_get_le32(params + 0x00) & 0x3ffU));
    value = (params[0x08] & 0xffU) |
        ((regtrace_t23_get_le32(params + 0x0c) << 8) & 0xffffU) |
        ((regtrace_t23_get_le32(params + 0x10) & 0x1ffU) << 16) |
        (regtrace_t23_get_le32(params + 0x14) << 28);
    system_reg_write(base + 0x74, value);
    system_reg_write(base + 0x14,
                     regtrace_t23_get_le32(params + 0x18) & 0x7ffffU);
    system_reg_write(base + 0x10,
                     regtrace_t23_get_le32(params + 0x1c) & 0x7ffffU);

    out_control = (msca_ch_out[channel * 2U] & 0x3U) |
        ((msca_ch_out[channel * 2U + 1U] & 0x1U) << 6);
    system_reg_write(base + 0x28, out_control);
    return system_reg_write(base + 0x28, 0);
}

static unsigned char *regtrace_t23_msca_hard_param(uint32_t channel)
{
    unsigned char *cfg = NULL;

    if (channel >= 3)
        return NULL;
    memcpy(&cfg, mscaHardPar + channel * sizeof(cfg), sizeof(cfg));
    return cfg;
}

static void regtrace_t23_msca_set_hard_param(uint32_t channel,
                                             unsigned char *cfg)
{
    if (channel < 3)
        memcpy(mscaHardPar + channel * sizeof(cfg), &cfg, sizeof(cfg));
}

static void regtrace_t23_msca_write_curve_axis(const uint16_t *curve,
                                                const uint16_t *control,
                                                bool use_control,
                                                uint32_t table_base)
{
    uint32_t entry;

    for (entry = 0; entry < 9; entry++) {
        uint32_t coefficient = entry * 2U;
        uint32_t low;
        uint32_t high = 0;

        if (use_control && coefficient < 4U)
            low = control[coefficient];
        else
            low = curve[coefficient];
        if (coefficient + 1U < 17U) {
            if (use_control && coefficient + 1U < 4U)
                high = control[coefficient + 1U];
            else
                high = curve[coefficient + 1U];
        }

        system_reg_write(0xe004U,
                         ((high & 0x1fffU) << 16) |
                         (low & 0x1fffU));
        system_reg_write(0xe004U, table_base + entry * 4U);
    }
}

int32_t tisp_msca_ch_curve_write(uint32_t unused, uintptr_t count_ptr)
{
    uint16_t *count = (uint16_t *)count_ptr;
    uint16_t *curves_h[3] = {
        (uint16_t *)msca_ch0_lanczos_h,
        (uint16_t *)msca_ch1_lanczos_h,
        (uint16_t *)msca_ch2_lanczos_h,
    };
    uint16_t *curves_w[3] = {
        (uint16_t *)msca_ch0_lanczos_w,
        (uint16_t *)msca_ch1_lanczos_w,
        (uint16_t *)msca_ch2_lanczos_w,
    };
    uint16_t *controls_h[3] = {
        (uint16_t *)msca_ch0_scale_ctl_h,
        (uint16_t *)msca_ch1_scale_ctl_h,
        (uint16_t *)msca_ch2_scale_ctl_h,
    };
    uint16_t *controls_w[3] = {
        (uint16_t *)msca_ch0_scale_ctl_w,
        (uint16_t *)msca_ch1_scale_ctl_w,
        (uint16_t *)msca_ch2_scale_ctl_w,
    };
    uint32_t channel;

    (void)unused;
    if (!count)
        return -EINVAL;

    for (channel = 0; channel < 3; channel++) {
        unsigned char *cfg = regtrace_t23_msca_hard_param(channel);
        uint32_t table_base;

        if (!cfg || cfg[0] != 1)
            continue;
        table_base = 0x800U + channel * 0x60U;
        regtrace_t23_msca_write_curve_axis(
            curves_h[channel], controls_h[channel],
            msca_ch_ctl_mode[channel * 2U] == 1, table_base);
        regtrace_t23_msca_write_curve_axis(
            curves_w[channel], controls_w[channel],
            msca_ch_ctl_mode[channel * 2U + 1U] == 1,
            table_base + 0x30U);
        *count += 18;
    }
    return 0;
}

