/* WHOLE_DRIVER_CANDIDATE fn_0000000000019a70 origin=fragment_seed original=tisp_msca_write_reg */
static int32_t tisp_msca_write_reg(void)
{
    uint32_t min_left = 0xffffU;
    uint32_t min_top = 0xffffU;
    uint32_t max_right = 0;
    uint32_t max_bottom = 0;
    uint32_t source_width;
    uint32_t source_height;
    uint32_t channel;
    bool active = false;

    for (channel = 0; channel < 3; channel++) {
        unsigned char *cfg = regtrace_t23_msca_hard_param(channel);
        uint32_t left;
        uint32_t top;
        uint32_t right;
        uint32_t bottom;

        if (!cfg || !cfg[0])
            continue;
        active = true;
        left = regtrace_t23_get_le32(cfg + 0x10) & 0xffffU;
        top = regtrace_t23_get_le32(cfg + 0x14) & 0xffffU;
        right = (left + regtrace_t23_get_le32(cfg + 0x18)) & 0xffffU;
        bottom = (top + regtrace_t23_get_le32(cfg + 0x1c)) & 0xffffU;
        if (left < min_left)
            min_left = left;
        if (top < min_top)
            min_top = top;
        if (right > max_right)
            max_right = right;
        if (bottom > max_bottom)
            max_bottom = bottom;
    }

    if (!active) {
        source_width = regtrace_t23_get_le32(tisp_par_info + 0);
        source_height = regtrace_t23_get_le32(tisp_par_info + 4);
        min_left = 0;
        min_top = 0;
        max_right = source_width ? source_width : regtrace_t23_source_sensor_width;
        max_bottom = source_height ? source_height : regtrace_t23_source_sensor_height;
    }

    system_reg_write(0xd090U,
                     ((min_left & 0x1fffU) << 16) |
                     (min_top & 0x0fffU));
    system_reg_write(0xd094U,
                     (((max_right - min_left) & 0x1fffU) << 16) |
                     ((max_bottom - min_top) & 0x0fffU));
    tisp_msca_scaling_algorithm();
    system_reg_write(0xd010U, 1);
    return 0;
}

int32_t tisp_msca_curve_calc(uint32_t path, uint32_t channel)
{
    unsigned char *cfg;
    int16_t *curve_h;
    int16_t *curve_w;
    uint32_t source_width;
    uint32_t source_height;
    uint32_t target_width;
    uint32_t target_height;
    uint32_t ratio_h;
    uint32_t ratio_w;
    int ret;

    (void)path;
    channel &= 0xffU;
    cfg = regtrace_t23_msca_hard_param(channel);
    if (!cfg || channel >= 3)
        return -EINVAL;

    source_width = regtrace_t23_get_le32(cfg + 0x18);
    source_height = regtrace_t23_get_le32(cfg + 0x1c);
    target_width = regtrace_t23_get_le32(cfg + 0x20);
    target_height = regtrace_t23_get_le32(cfg + 0x24);
    if (!source_width || !source_height || !target_width || !target_height)
        return -EINVAL;

    ratio_w = (target_width << 14) / source_width;
    ratio_h = (target_height << 14) / source_height;
    if (ratio_w >= 27307U)
        ratio_w = 27306U;
    if (ratio_h >= 27307U)
        ratio_h = 27306U;

    if (channel == 0) {
        curve_h = (int16_t *)msca_ch0_lanczos_h;
        curve_w = (int16_t *)msca_ch0_lanczos_w;
    } else if (channel == 1) {
        curve_h = (int16_t *)msca_ch1_lanczos_h;
        curve_w = (int16_t *)msca_ch1_lanczos_w;
    } else {
        curve_h = (int16_t *)msca_ch2_lanczos_h;
        curve_w = (int16_t *)msca_ch2_lanczos_w;
    }

    ret = tx_isp_t23_scaler_curve_generate(
        ratio_w, curve_w, TX_ISP_T23_SCALER_COEFFICIENTS);
    if (ret)
        return ret;
    ret = tx_isp_t23_scaler_curve_generate(
        ratio_h, curve_h, TX_ISP_T23_SCALER_COEFFICIENTS);
    if (ret)
        return ret;

    printk(KERN_WARNING "t23: T23 MSCA curves ch=%u ratio=%u/%u sums=%d/%d\n",
           channel, ratio_w, ratio_h,
           curve_w[0] + curve_w[8] + curve_w[16],
           curve_h[0] + curve_h[8] + curve_h[16]);
    return 0;
}

