    uint32_t base;
    uint32_t cfg_word;
    uint32_t work;
    int ret;

    (void)unused;
    channel &= 0xffU;
    if (!cfg || channel >= 3)
        return -EINVAL;

    t23_crumb(T23C_CFG_LOAD, channel);
    /* reloaded below: valid again only once the load completed */
    regtrace_t23_msca_live_valid[channel] = false;
    ret = tisp_msca_para_calc(0, channel, cfg_ptr);
    if (ret)
        return ret;
    regtrace_t23_msca_set_hard_param(channel, cfg);
    if (regtrace_t23_source_msca_curves) {
        ret = tisp_msca_curve_calc(unused, channel);
        if (ret)
            return ret;
        ret = tisp_msca_ch_curve_write_ctrl(unused);
        if (ret)
            return ret;
    }
    ret = tisp_msca_init_chx_cfg(0, channel, cfg_ptr);
    if (ret)
        return ret;
