/* Unlock the front crop: every channel record gets the full sensor window
 * and loses the lock byte, running channels are reloaded and latched. */
static void regtrace_t23_fcrop_unlock(const char *why)
{
    unsigned long flags;
    uint32_t channel;
    bool was = fcrop_en != 0;

    spin_lock_irqsave(&regtrace_t23_msca_lock, flags);
    for (channel = 0; channel < 3U; channel++) {
        unsigned char *cfg = msca + channel * 56U;

        if (cfg[3])
            was = true;
        regtrace_t23_put_le32(cfg + 0x10, 0);
        regtrace_t23_put_le32(cfg + 0x14, 0);
        regtrace_t23_put_le32(cfg + 0x18, regtrace_t23_source_sensor_width);
        regtrace_t23_put_le32(cfg + 0x1c, regtrace_t23_source_sensor_height);
        cfg[3] = 0;
    }
    if (was) {
        for (channel = 0; channel < 3U; channel++) {
            unsigned char *cfg = msca + channel * 56U;

            if (cfg[0] && regtrace_t23_core_started)
                tisp_msca_chx_cfg_load(0, channel, (uintptr_t)cfg);
        }
        system_reg_write(0xd010U, 1);
    }
    fcrop_en = 0;
    spin_unlock_irqrestore(&regtrace_t23_msca_lock, flags);
    if (was)
        printk(KERN_WARNING "t23: front crop %s: full sensor window restored\n",
               why);
}

/*
 * Stock tisp_msca_api_set_fcrop (0x1b34c), reached from the 0x80000e3 control
 * as (0, enable, top, left, width, height).  With enable set every channel
 * takes the window as its sensor-side input (left/top/width/height at
 * +0x10..+0x1c), locks it against the channel attributes (+3) and has its
 * scaler parameters, curves and channel configuration recomputed, then the
 * shadow registers are latched (0xd010).  enable == 0 only logs and clears
 * fcrop_en: the stock module leaves the last window in place.  Channels that
 * are not running get the window for their next start; the running ones are
 * reloaded through this driver's channel load (same OEM call order).
 */
int32_t tisp_msca_api_set_fcrop(uint32_t a0, uint32_t a1, uint32_t a2,
                                uint32_t a3, uint32_t arg4, uint32_t arg5)
{
    uint32_t enable = a1 & 0xffU;
    uint32_t channel;
    unsigned long flags;

    (void)a0;
    if (!enable) {
        /* Stock only clears fcrop_en and keeps the window locked in the
         * channel records until the module is reloaded: the picture stayed
         * cropped, and a later larger channel output stalled the MSCA
         * (vorne, 10-09).  Unlock and give the channels the full sensor
         * window again (beyond stock). */
        regtrace_t23_fcrop_unlock("disabled");
        return 0;
    }
    /* not while the core ISR drains/reprograms the same MSCA channels */
    spin_lock_irqsave(&regtrace_t23_msca_lock, flags);
    for (channel = 0; channel < 3U; channel++) {
        unsigned char *cfg = msca + channel * 56U;

        regtrace_t23_put_le32(cfg + 0x10, a3);      /* left */
        regtrace_t23_put_le32(cfg + 0x14, a2);      /* top */
        regtrace_t23_put_le32(cfg + 0x18, arg4);    /* width */
        regtrace_t23_put_le32(cfg + 0x1c, arg5);    /* height */
        cfg[3] = 1;
    }
    /* all windows first: the channel origins are relative to their union */
    for (channel = 0; channel < 3U; channel++) {
        unsigned char *cfg = msca + channel * 56U;

        if (cfg[0] && regtrace_t23_core_started)
            tisp_msca_chx_cfg_load(0, channel, (uintptr_t)cfg);
    }
    system_reg_write(0xd010U, 1);
    fcrop_en = enable;
    spin_unlock_irqrestore(&regtrace_t23_msca_lock, flags);
    printk(KERN_INFO "t23: front crop top=%u left=%u %ux%u\n",
           a2, a3, arg4, arg5);
    return 0;
}

