/*
 * Sensor flip as last requested through the sensor-flip controls (bit 0
 * mirror, bit 1 flip), or -1 while the sensor still runs as it was loaded,
 * in which case source_lsc_initial_flip/mirror describe it.  The LSC mesh
 * has to follow the sensor orientation.
 */
static int regtrace_t23_sensor_flip_mode = -1;

static int regtrace_t23_lsc_follow_sensor_flip(void)
{
    uint32_t flip;
    uint32_t mirror;

    if (regtrace_t23_sensor_flip_mode < 0) {
        flip = regtrace_t23_source_lsc_initial_flip ? 1U : 0U;
        mirror = regtrace_t23_source_lsc_initial_mirror ? 1U : 0U;
    } else {
        flip = ((uint32_t)regtrace_t23_sensor_flip_mode >> 1) & 1U;
        mirror = (uint32_t)regtrace_t23_sensor_flip_mode & 1U;
    }
    if (!regtrace_t23_source_lsc_tuning_init ||
        !regtrace_t23_source_lsc_tables_initialized)
        return 0;
    if ((uint32_t)last_status_flip_en == flip &&
        (uint32_t)last_status_mirror_en == mirror)
        return 0;
    return tisp_lsc_mirror_flip(0, regtrace_t23_source_sensor_width,
                                regtrace_t23_source_sensor_height,
                                flip, mirror);
}

/*
 * Keep the AE and AWB work off the shared tuning arrays while a bank
 * switch reloads them.  New captures are refused while paused; queued work
 * is dropped and running work is waited for.
 */
static void regtrace_t23_source_algo_pause(void)
{
    unsigned long flags;

    spin_lock_irqsave(&regtrace_t23_ae_hlil_lock, flags);
    regtrace_t23_ae_hlil_paused = true;
    spin_unlock_irqrestore(&regtrace_t23_ae_hlil_lock, flags);
    cancel_work_sync(&regtrace_t23_source_ae_hlil_work_item);

    spin_lock_irqsave(&regtrace_t23_awb_hlil_lock, flags);
    regtrace_t23_awb_hlil_paused = true;
    spin_unlock_irqrestore(&regtrace_t23_awb_hlil_lock, flags);
    cancel_work_sync(&regtrace_t23_source_awb_hlil_work_item);
}

static void regtrace_t23_source_algo_resume(void)
{
    unsigned long flags;

    spin_lock_irqsave(&regtrace_t23_awb_hlil_lock, flags);
    regtrace_t23_awb_hlil_pending = false;
    regtrace_t23_awb_hlil_paused = false;
    spin_unlock_irqrestore(&regtrace_t23_awb_hlil_lock, flags);

    spin_lock_irqsave(&regtrace_t23_ae_hlil_lock, flags);
    regtrace_t23_ae_hlil_pending = false;
    regtrace_t23_ae_hlil_paused = false;
    spin_unlock_irqrestore(&regtrace_t23_ae_hlil_lock, flags);
}

/*
 * Per-block parameter reload after the active bank changed, the source-path
 * equivalent of the OEM *_dn_params_refresh plan in tisp_day_or_night_s_ctrl
 * (defog, AE, AWB, DMSC, sharpen, MDNS, SDNS, GIB, LSC, CCM, CLM, gamma,
 * ADR, DPC, AF, BCSH, YDNS).  Every block this driver initialised from the
 * IQ bank is read again from the new active bank and rewritten; user
 * settings (BCSH values, sinter/temper/DPC/DRC/defog strengths, the sensor
 * flip of the LSC mesh) are applied on top again.  CCM and the AWB colour
 * bias are reloaded by regtrace_t23_source_ccm_select_bank().  AE and AWB
 * keep their HLIL state; AF is not initialised by this driver.  Sharpen is
 * reloaded and rewritten at its last gain like the OEM
 * tiziano_sharpen_dn_params_refresh.  The gain-driven blocks are then
 * rewritten at the gain in use.
 *
 * Only while the core runs: a stream start loads every block from the
 * active bank anyway.
 */
static void regtrace_t23_source_dn_params_refresh(const char *reason)
{
    uint32_t gain = regtrace_t23_dmsc_gain_q16 ?
        regtrace_t23_dmsc_gain_q16 : 0x10000U;
    uint32_t failed = 0;
    int ret;

    if (!regtrace_t23_source_core_start || !regtrace_t23_core_started)
        return;

    if (regtrace_t23_source_gib_tuning_init &&
        regtrace_t23_source_gib_write_tuning_startup())
        failed |= BIT(0);
    if (regtrace_t23_source_gamma_tuning_init &&
        tiziano_gamma_dn_params_refresh())
        failed |= BIT(1);
    if (regtrace_t23_source_lsc_tuning_init) {
        if (tiziano_lsc_dn_params_refresh()) {
            failed |= BIT(2);
        } else {
            (void)regtrace_t23_lsc_follow_sensor_flip();
            regtrace_t23_source_lsc_update_pending = true;
            (void)tisp_lsc_write_lut_datas();
        }
    }
    if (regtrace_t23_source_dpc_tuning_init &&
        tiziano_dpc_params_refresh())
        failed |= BIT(3);
    if (regtrace_t23_source_ydns_tuning_init &&
        tiziano_ydns_params_refresh())
        failed |= BIT(4);
    if (regtrace_t23_source_dmsc_tuning_init &&
        tiziano_dmsc_params_refresh())
        failed |= BIT(5);
    if (regtrace_t23_source_bcsh_tuning_init) {
        tiziano_bcsh_params_refresh();
        if (!regtrace_t23_source_bcsh_tuning_status) {
            tiziano_bcsh_Tccm_Comp2Orig();
            BCSH_real = 1;
            tiziano_bcsh_update();
        } else {
            failed |= BIT(6);
        }
    }
    if (regtrace_t23_source_clm_tuning_init) {
        if (!regtrace_t23_source_clm_load_tuning()) {
            clm_ct_value_old = 0xffffU;
            clm_ct_part_old = 0xffU;
            if (tisp_clm_interp_by_ct(0, regtrace_t23_source_clm_runtime_ct,
                                      1U) > 0)
                tiziano_set_parameter_clm();
        } else {
            failed |= BIT(7);
        }
    }
    if (regtrace_t23_source_mdns_initialized &&
        regtrace_t23_source_mdns_load_tuning())
        failed |= BIT(8);
    if (regtrace_t23_source_sdns_initialized &&
        regtrace_t23_source_sdns_load_tuning())
        failed |= BIT(9);
    if (regtrace_t23_source_adr_oem) {
        t23_adrlift_dn_refresh();
    } else if (regtrace_t23_source_adr_initialized) {
        if (!regtrace_t23_source_adr_load_tuning()) {
            tiziano_adr_params_init();
            if (regtrace_t23_adr_ratio != 0x80U)
                regtrace_t23_adr_strength_apply();
        } else {
            failed |= BIT(10);
        }
    }
    if (regtrace_t23_source_adr_oem) {
        /* refreshed with ADR above */
    } else if (regtrace_t23_source_defog_initialized) {
        if (!regtrace_t23_source_defog_load_tuning())
            regtrace_t23_defog_strength_apply();
        else
            failed |= BIT(11);
    }
    /* OEM: tiziano_af_dn_params_refresh (source_af=1) */
    t23_af_dn_refresh();
    /* OEM order: tiziano_ae_dn_params_refresh after defog.  The lifted
     * stock AE0 reloads its parameters from the new bank like stock; the
     * HLIL substitute keeps its state. */
    if (regtrace_t23_source_ae_oem && t23_aelift_ready) {
        flush_work(&t23_aelift_work);
        mutex_lock(&t23_aelift_mutex);
        t23_aelift_set_busy(true);
        T23_AELIFT_CALL(LA_tiziano_ae_dn_params_refresh, 0, 0, 0, 0);
        t23_aelift_set_busy(false);
        mutex_unlock(&t23_aelift_mutex);
    }
    /* OEM: curves from the new bank, all registers at the current gain. */
    if (regtrace_t23_source_sharpen_initialized &&
        tiziano_sharpen_dn_params_refresh())
        failed |= BIT(12);

    /* Rewrite the gain-interpolated blocks once at the gain in use. */
    regtrace_t23_dpc_gain_old = 0xffffffffU;
    ydns_gain_old = 0xffffffffU;
    regtrace_t23_dmsc_gain_old = 0xffffffffU;
    if (regtrace_t23_source_mdns_initialized)
        regtrace_t23_source_mdns_gain_old = 0xffffffffU;
    if (regtrace_t23_source_sdns_initialized)
        regtrace_t23_source_sdns_gain_old = 0xffffffffU;
    ret = regtrace_t23_source_apply_total_gain_value(gain, 0, true, true);

    /* A block whose parameters did not reload from the new bank is
     * bypassed rather than run with the previous bank's (the next switch
     * or stream start rebuilds 0xc from the bank again).  Demosaic stays:
     * without it there is no colour picture at all. */
    if (failed) {
        /*
         * Stock bit layout: LSC 6 (tiziano_lsc_init, tisp_ct_update), CLM
         * 13 and BCSH 16 (tisp_ct_update, tisp_s_ccm_attr), ADR 7 and
         * defog 11 (tisp_long_ev_update), DPC 4 (IMPISPModuleCtl; bit 2 is
         * the AWB gain stage and must not be bypassed for a DPC failure).
         */
        static const uint8_t block_bit[13] = {
            5,  /* GIB */     10, /* gamma */   6,  /* LSC */
            4,  /* DPC */     17, /* YDNS */    0xff, /* DMSC */
            16, /* BCSH */    13, /* CLM */     16, /* MDNS */
            15, /* SDNS */    7,  /* ADR */     11, /* defog */
            14, /* sharpen */
        };
        uint32_t bypass = 0;
        unsigned int i;

        for (i = 0; i < ARRAY_SIZE(block_bit); ++i)
            if ((failed & BIT(i)) && block_bit[i] != 0xff)
                bypass |= BIT(block_bit[i]);
        if (bypass)
            system_reg_write(0x0cU, system_reg_read(0x0cU) | bypass);
    }

    /* a clean refresh is a progress note (quiet unless t23_runtime_trace) */
    if (failed || ret)
        printk(KERN_WARNING
               "t23: bank switch block refresh reason=%s gain=0x%x tgain_log2=0x%x failed=0x%x ret=%d r0c=0x%08x\n",
               reason ? reason : "?", gain, regtrace_t23_tgain_log2, failed,
               ret, system_reg_read(0x0cU));
    else
        printk(KERN_INFO
               "t23: bank switch block refresh reason=%s gain=0x%x tgain_log2=0x%x r0c=0x%08x\n",
               reason ? reason : "?", gain, regtrace_t23_tgain_log2,
               system_reg_read(0x0cU));
}

/* WHOLE_DRIVER_CANDIDATE fn_0000000000064c48 origin=fragment_seed original=tisp_day_or_night_s_ctrl */
int64_t tisp_day_or_night_s_ctrl(uintptr_t a0, uint32_t a1)
{
    uint32_t *active = (uint32_t *)(void *)(tparams + T23_TPARAMS_ACTIVE_OFFSET);
    const void *selected;
    int ret;

    if (a0 >= sizeof(day_night) / sizeof(uint32_t))
        return -EINVAL;
    if (a1 > 1)
        return -EINVAL;

    /* bank mutex: a SwitchBin publish never runs between the pick and the use */
    mutex_lock(&regtrace_t23_bank_mutex);
    selected = (const void *)(a1 == 0 ? tparams_day : tparams_night);
    if (!selected) {
        mutex_unlock(&regtrace_t23_bank_mutex);
        return -ENODEV;
    }

    regtrace_t23_source_algo_pause();
    ret = regtrace_t23_source_ccm_select_bank(selected);
    if (ret) {
        regtrace_t23_source_algo_resume();
        mutex_unlock(&regtrace_t23_bank_mutex);
        return ret;
    }

    memcpy(active, selected, T23_TPARAMS_BANK_SIZE);
    *(uint32_t *)(void *)(tisp_par_info + a0 * 156U + 124U) = a1;
    regtrace_t23_dn_night = a1 == 1;
    *(uint32_t *)(void *)(day_night + a0 * sizeof(uint32_t)) = 0;

    if (regtrace_t23_source_core_start) {
        regtrace_t23_source_mode_flags_apply(active);
        regtrace_t23_source_dn_params_refresh(a1 ? "night" : "day");
        /* mono at night, the active CSC preset's clip by day */
        if (regtrace_t23_core_started)
            regtrace_t23_csc_write_current();
    } else {
        tx_isp_t23_mode_profile_apply(active);
    }
    regtrace_t23_source_algo_resume();
    mutex_unlock(&regtrace_t23_bank_mutex);

    cust_mode = 0;
    *(uint8_t *)(void *)&tispPollValue = 1;
    *((uint8_t *)(void *)&tispPollValue + 2) =
        day_night[a0 * sizeof(uint32_t)];
    wake_up_interruptible(&dumpQueue);

    return 0;
}

/* WHOLE_DRIVER_CANDIDATE fn_0000000000064f18 origin=fragment_seed original=tisp_cust_mode_s_ctrl */
int32_t tisp_cust_mode_s_ctrl(uint32_t arg1, uint32_t arg2)
{
    uint32_t *active = (uint32_t *)(void *)(tparams + T23_TPARAMS_ACTIVE_OFFSET);
    const void *selected = NULL;
    uint32_t dn;
    int ret;

    mutex_lock(&regtrace_t23_bank_mutex);
    if (!tparams_cust) {
        /* no custom bank: DISABLE is a no-op (issue 122), ENABLE fails */
        mutex_unlock(&regtrace_t23_bank_mutex);
        return (arg2 == 0 && !cust_mode) ? 0 : -1;
    }

    if (arg2 == 1) {
        selected = (const void *)tparams_cust;
    } else if (arg2 == 0) {
        if (arg1 >= sizeof(day_night) / sizeof(uint32_t)) {
            mutex_unlock(&regtrace_t23_bank_mutex);
            return -EINVAL;
        }
        dn = *(uint32_t *)(void *)(day_night + arg1 * sizeof(uint32_t));
        if (dn == 0)
            selected = (const void *)tparams_day;
        else if (dn == 1)
            selected = (const void *)tparams_night;
    }

    if (!selected) {
        mutex_unlock(&regtrace_t23_bank_mutex);
        return (arg2 == 0 || arg2 == 1) ? -ENODEV : 0;
    }

    regtrace_t23_source_algo_pause();
    ret = regtrace_t23_source_ccm_select_bank(selected);
    if (ret) {
        regtrace_t23_source_algo_resume();
        mutex_unlock(&regtrace_t23_bank_mutex);
        return ret;
    }
    memcpy(active, selected, T23_TPARAMS_BANK_SIZE);
    cust_mode = arg2 == 1;

    if (regtrace_t23_source_core_start) {
        regtrace_t23_source_mode_flags_apply(active);
        regtrace_t23_source_dn_params_refresh(arg2 == 1 ? "custom" :
                                              "custom-off");
    } else {
        tx_isp_t23_mode_profile_apply(active);
    }
    regtrace_t23_source_algo_resume();
    mutex_unlock(&regtrace_t23_bank_mutex);
    return 0;
}

/* WHOLE_DRIVER_CANDIDATE fn_000000000006519c origin=fragment_seed original=tisp_cust_mode_g_ctrl */
uint32_t tisp_cust_mode_g_ctrl(void)
{
    /* DISABLE (0) until a custom bank is active; the old answer without a
     * *-cust-t23.bin was 0xffffffff, not an IMPISPTuningOpsMode (issue 122) */
    return (uint32_t)cust_mode;
}

/* WHOLE_DRIVER_CANDIDATE fn_00000000000651bc origin=fragment_seed original=tisp_day_or_night_g_ctrl */
static int32_t tisp_day_or_night_g_ctrl(uint32_t a0)
{
    if (a0 >= sizeof(tisp_par_info) / 156U)
        return -EINVAL;
    return *(uint32_t *)(void *)(tisp_par_info + a0 * 156U + 124U);
}

/*
 * tisp_switch_bin / tisp_core_switch_bin (stock 0x651d8 / 0x17b0c), SwitchBin
 * (control 0x8000185).  Stock reads the file over the live day/night banks
 * and checks it afterwards.  Here (as T41 SwitchBin) in two steps:
 *   prepare  the file is read and checked (size, "2.20"/"header0", CRC) into
 *            a private pair of bank buffers; no live pointer, bank or
 *            register is touched, any failure returns before the commit.
 *            Runs without the tuning mutex (file I/O may block).
 *   commit   under the tuning and the bank mutex, with AE/AWB paused: the
 *            bank of the running mode is selected from the NEW buffer first
 *            (regtrace_t23_source_ccm_select_bank restores the old state
 *            itself on failure, then the new buffers are simply freed), and
 *            only after it succeeded the new pair is published by pointer.
 *            The old banks are never overwritten: they are retired one
 *            generation (freed with the next SwitchBin or at deinit).
 * A running custom mode keeps its bank; the new day/night banks apply when
 * it is left.  Not reproduced: the stock post-step that stores a day/night
 * state word of the lifted sensor object.
 * Host build only, device test pending.
 */
static int regtrace_t23_switch_bin_prepare(const char *path,
                                           unsigned char **day_out,
                                           unsigned char **night_out)
{
    unsigned char *blob, *day, *night;
    int ret;

    blob = private_vmalloc(T23_IQ_STANDARD_SIZE);
    if (!blob)
        return -ENOMEM;
    ret = regtrace_t23_read_file_exact(path, blob, T23_IQ_STANDARD_SIZE);
    if (!ret)
        ret = regtrace_t23_validate_iq(blob, T23_IQ_STANDARD_SIZE,
                                       2U * T23_TPARAMS_BANK_SIZE);
    if (ret) {
        printk(KERN_ERR "tx_isp_t23_recovered: SwitchBin %s rejected ret=%d\n",
               path, ret);
        private_vfree(blob);
        return ret;
    }
    day = private_vmalloc(T23_TPARAMS_BANK_SIZE);
    night = private_vmalloc(T23_TPARAMS_BANK_SIZE);
    if (!day || !night) {
        if (day)
            private_vfree(day);
        if (night)
            private_vfree(night);
        private_vfree(blob);
        return -ENOMEM;
    }
    memcpy(day, blob + T23_IQ_HEADER_SIZE, T23_TPARAMS_BANK_SIZE);
    memcpy(night, blob + T23_IQ_HEADER_SIZE + T23_TPARAMS_BANK_SIZE,
           T23_TPARAMS_BANK_SIZE);
    private_vfree(blob);
    *day_out = day;
    *night_out = night;
    return 0;
}

/* Takes over day and night (published or freed).  Caller holds the tuning mutex. */
static int regtrace_t23_switch_bin_commit(unsigned char *day,
                                          unsigned char *night)
{
    uint32_t *active = (uint32_t *)(void *)(tparams + T23_TPARAMS_ACTIVE_OFFSET);
    const unsigned char *running;
    const void *selected = NULL;
    uintptr_t old_day, old_night;
    int ret = 0;

    mutex_lock(&regtrace_t23_bank_mutex);
    if (!tparams_day || !tparams_night) {
        ret = -ENODEV;
        goto fail;
    }
    regtrace_t23_source_algo_pause();
    running = regtrace_t23_source_active_bank;
    if (running == (const unsigned char *)tparams_day)
        selected = day;
    else if (running == (const unsigned char *)tparams_night)
        selected = night;
    if (selected) {
        ret = regtrace_t23_source_ccm_select_bank(selected);
        if (ret) {
            regtrace_t23_source_algo_resume();
            goto fail;
        }
    }

    /* nothing below can fail */
    old_day = tparams_day;
    old_night = tparams_night;
    smp_wmb();                  /* the new buffers are complete before they are visible */
    ACCESS_ONCE(tparams_day) = (uintptr_t)day;
    ACCESS_ONCE(tparams_night) = (uintptr_t)night;
    if (regtrace_t23_bank_retired_night)
        private_vfree((void *)regtrace_t23_bank_retired_night);
    if (regtrace_t23_bank_retired_day)
        private_vfree((void *)regtrace_t23_bank_retired_day);
    regtrace_t23_bank_retired_day = old_day;
    regtrace_t23_bank_retired_night = old_night;

    if (selected)
        memcpy(active, selected, T23_TPARAMS_BANK_SIZE);
    if (regtrace_t23_source_core_start) {
        regtrace_t23_source_mode_flags_apply(active);
        regtrace_t23_source_dn_params_refresh("switch-bin");
    } else {
        tx_isp_t23_mode_profile_apply(active);
    }
    regtrace_t23_source_algo_resume();
    mutex_unlock(&regtrace_t23_bank_mutex);

    *(uint8_t *)(void *)&tispPollValue = 1;
    *((uint8_t *)(void *)&tispPollValue + 3) = 1;
    wake_up_interruptible(&dumpQueue);
    return 0;

fail:
    mutex_unlock(&regtrace_t23_bank_mutex);
    private_vfree(day);
    private_vfree(night);
    return ret;
}

/*
 * a0 is a KERNEL pointer to the 68 byte block { u32 enable, char path[64] }
 * (enable checked and path terminated by the caller).  Caller holds the
 * tuning mutex; the isp-m0 ext dispatcher uses prepare/commit directly so
 * the file is read before it takes the mutex.
 */
uint32_t tisp_switch_bin(uint32_t a0)
{
    unsigned char *day, *night;
    int ret;

    ret = regtrace_t23_switch_bin_prepare((const char *)(uintptr_t)a0 + 4,
                                          &day, &night);
    if (!ret)
        ret = regtrace_t23_switch_bin_commit(day, night);
    return (uint32_t)ret;
}

/* WHOLE_DRIVER_CANDIDATE fn_00000000000654b4 origin=model_output original=tisp_mirror_enable */
static int32_t tisp_mirror_enable(int32_t arg1, char arg2)
{
	void *s2;
	char *s1;
	void *s0;

	s2 = (void *)(long)arg1;
	s1 = (int32_t *)(arg2 & 0xff);

	private_vmalloc(0x90c);
	s0 = 0;

	*((char *)(s0 + 0x12)) = s1;
	*((char *)(s0 + 0x272)) = s1;
	*((char *)(s0 + 0x4d2)) = s1;

	tisp_msca_api_set_mirr_flip(arg1, s0);

	if (s0 == 0)
		return 0;

	private_vfree(s0);
	return 0;
}

/* WHOLE_DRIVER_CANDIDATE fn_0000000000065544 origin=model_output original=tisp_hv_flip_enable */
/**
 * tisp_hv_flip_enable - Configure mirror flip settings in a buffer.
 *
 * @arg1: First argument passed to tisp_msca_api_set_mirr_flip.
 * @arg2: Bit field controlling which bytes to write.
 *         bit 0 -> write 0x01 at offsets 0x12, 0x272, 0x4d2
 *         bit 1 -> write 0x01 at offsets 0x13, 0x273, 0x4d3
 */
int32_t tisp_hv_flip_enable(int32_t arg1, char arg2)
{
	void *v0;
	uint32_t *s1;
	char *v0_1;
	char a1_1;

	/* Allocate 0x90c bytes via private_vmalloc */
	private_vmalloc(0x90c);
	v0 = 0;

	/* Extract bit fields from arg2 */
	s1 = (int32_t *)(uint8_t)arg2;
	v0_1 = (char *)((uintptr_t)s1 & 1);
	a1_1 = (char)(((uintptr_t)s1 >> 1) & 1);

	/* Write v0_1 to offsets 0x12, 0x272, 0x4d2 */
	((char *)v0)[0x12] = v0_1;
	((char *)v0)[0x272] = v0_1;
	((char *)v0)[0x4d2] = v0_1;

	/* Write a1_1 to offsets 0x13, 0x273, 0x4d3 */
	((char *)v0)[0x13] = a1_1;
	((char *)v0)[0x273] = a1_1;
	((char *)v0)[0x4d3] = a1_1;

	/* Call tisp_msca_api_set_mirr_flip(arg1, v0) */
	tisp_msca_api_set_mirr_flip(arg1, v0);

	/* If v0 is NULL, return 0 */
	if (v0 == NULL)
		return 0;

	/* Tail-call-like: free and return result */
	private_vfree(v0);
	return 0;
}

